package dev.infend.skyrimtext;

/**
 * Rich, offline Russian narrative for every game-engine scene.
 * The original quest state and actions are kept unchanged. Text is written
 * specifically for this project, never imported from another game.
 *
 * Dialogue formatting: **Имя:**
 * >**— Реплика**
 */
public final class SceneNarrative {
    private SceneNarrative(){}

    private static final String[] LANDSCAPES={
        "Равнины вокруг Вайтрана золотятся даже под бледным небом. Ветер наклоняет сухую траву, и волны пробегают по ней до самых сторожевых холмов. Над городом возвышается Драконий Предел; его крыша видна задолго до ворот, но расстояние в степи обманчиво. От дороги тянет пылью, овечьей шерстью и дымом утренних костров.",
        "Рифтен отражается в чёрной воде озера Инальта золотистыми окнами таверн. Мокрый настил у причала подаётся под сапогом, на старых ступенях стоит запах рыбы и гнилых листьев. Люди здесь говорят осторожно: одни покупают молчание септимами, другие надеются узнать чужую тайну раньше, чем она станет товаром.",
        "Солёный ветер Виндхельма бьёт в каменные лица древних статуй и обдирает пальцы даже сквозь рукавицы. За стенами дымят кузницы, по мосту звенят копыта, а из серых дворов тянутся длинные тени. В городе помнят слишком много войн, и каждый встречный сначала приглядывается к твоей одежде, а уже затем к лицу.",
        "Белые башни Солитьюда прячутся в морской дымке. Над гаванью кричат чайки, под арками гремят повозки, а ветер приносит с рынка запах печёного хлеба и солёной рыбы. Дворцовая стража держится безукоризненно прямо; здесь даже обычная новость может обернуться политическим решением.",
        "Маркарт вырублен в скале настолько глубоко, что шаги словно остаются внутри его стен. Вода с карнизов падает на серую брусчатку, металлические двери отзываются долгим эхом, а над ущельем висят каменные переходы. Древние механизмы под городом давно умолкли, но люди всё равно прислушиваются к ночным ударам.",
        "Леса Фолкрита густы и неподвижны. Под влажным мхом скрыты старые надгробия, из чёрной почвы поднимается запах грибов и прелых игл, а в чащобе порой слышится хруст, не похожий на шаги зверя. Здесь говорят о мёртвых спокойно, зато о живых путешественниках предпочитают спрашивать шёпотом.",
        "Винтерхолд стоит на кромке обрыва над ледяным морем. Ветер несёт ледяную крошку меж разрушенных стен, дальний гром накатывает с воды, а огромный каменный мост ведёт к огням Коллегии. Каждый житель города знает, как быстро мороз превращает минутную небрежность в смертельную ошибку.",
        "В Данстаре смолёные лодки скрипят у обледеневших причалов. С моря ползёт густой туман, и колокольчик у рыбацкой хижины звенит сам по себе, когда усиливается ветер. Шахтёры и моряки говорят о дурных снах, которые приходят к людям в одну и ту же ночь.",
        "Над болотами Морфала стоит тяжёлый серебристый туман. Чёрная вода неподвижна между корнями, тростник шелестит даже без ветра, а вдалеке то и дело вспыхивают огоньки, похожие на лампы у невидимых дверей. Здесь лучше узнать дорогу до наступления темноты, чем искать её по звёздам.",
        "На Солстейме пепел ложится на плащи серой пылью и скрипит на зубах. За прибрежными скалами растут странные гигантские грибы, пахнет серой и морской солью, а в глубине острова слышится гул, происхождение которого никто толком не объясняет. Местные научились отличать обычную бурю от опасной по цвету воздуха."
    };
    private static final String[] VOICES={
        "Стражник у ворот","Лодочник","Старый кузнец","Караульный дворца",
        "Двемерский знаток","Лесная охотница","Ученик Коллегии","Моряк","Болотная травница","Пепельный путник"
    };
    private static final String[] REMARKS={
        "На тракте снова видели следы у самой заставы. Не задерживайся в открытом поле, когда стемнеет.",
        "На воде проще потерять груз, чем имя. Но имя иногда приходится выкупать обратно.",
        "Сталь выдержит мороз. Человеческая решимость тоже, если не проверять её без нужды.",
        "У важных людей есть хорошие плащи, но и под ними сердце стучит от дурных вестей.",
        "Не всякая закрытая дверь скрывает сокровище. Некоторые лучше оставить запертыми.",
        "В нашем лесу не всё заблудившееся хочет, чтобы его находили.",
        "На руинах даже тишина служит предупреждением. Слушай её внимательнее.",
        "Море не обещает благополучного возвращения. Мы всё равно выходим на рассвете.",
        "Болото запоминает шаги. Не повторяй путь, если не знаешь, кто прошёл по нему первым.",
        "Пепел всё покрывает одинаково. А вот под ним скрываются совершенно разные вещи."
    };
    private static final String[] QUEST_MOMENTS={
        "Эйрн сидит за низким столом, на котором разложены потёртые карты. Его пальцы подрагивают не от старости: на краю одной карты видна обугленная метка, похожая на отпечаток ладони. За дверью постукивает дождь, и старик каждый раз замолкает, когда снаружи раздаётся чей-то шаг. Он не просит слепой веры, только проверить место, о котором больше никто не желает говорить.",
        "Между корнями древних сосен лежат плиты алтаря. Края камня обожжены, хотя земля вокруг мокрая после ночного дождя. Под слоем хвои едва видны насечки, а где-то в лесу перекликаются птицы. Эйрн предупреждал, что искать здесь нужно не блеск драгоценного металла, а следы чьей-то поспешной работы.",
        "Северное побережье встречает тебя колючей метелью. Винтерхолд кажется выцветшей тенью города, которым когда-то был. Над ледяными утёсами видна башня, чьи окна давно не светятся; сегодня в одном из них появляется тусклый отблеск. Лестница к входу обледенела, а на пороге лежит след тяжёлой ноги, не похожий на человеческий.",
        "Солитьюд встречает корабельными гудками и непрекращающимися спорами на площади. У хранителей есть люди при дворе, но нет желания навлекать лишнее внимание на старинные тайны. Найденные записи ты несёшь под плащом; их страницы пахнут железом, мокрой кожей и дымом. Осталось решить, кому доверить их окончательно.",
        "Бывшие участники экспедиции уже разошлись по своим дорогам. Печати снова целы, но на картах осталось несколько зачёркнутых мест, о которых никто не захотел говорить вслух. Победа не убрала из мира все опасности; она только дала людям время."
    };
    private static String dialogue(String person,String statement){
        return "**"+person+":**\n>**— "+statement+"**";
    }
    private static int region(GameEngine g){
        return Math.max(0,Math.min(LANDSCAPES.length-1,g.region));
    }
    private static String world(GameEngine g,GameEngine.Scene s){
        int r=region(g);
        String day=g.day%3==0?"К вечеру воздух темнеет, а в низинах рано сгущается тень.":"Дорога дышит пылью и сыростью; дневной свет находит каждый след на камнях.";
        return LANDSCAPES[r]+"\n\n"+day+
            " Ты находишься возле «"+g.progress.location+"». Рядом слышны голоса людей, которым нет дела до твоей славы, зато есть дело до того, переживут ли они следующую ночь. На перекрёстке замечаешь свежую колею, чужие сапоги и едва заметные следы копыт, уходящие за холм."+
            "\n\n"+dialogue(VOICES[r],REMARKS[r])+
            "\n\nНеподалёку спорят два путника. Один советует идти к ближайшему постоялому двору и расспросить местных, другой указывает на следы у тропы. Ты уже знаешь, как легко уверенный рассказ оказывается ложью. Слова собеседника заставляют вспомнить собственные обещания: какая-то часть пути ещё не завершена."+
            "\n\n"+dialogue("Попутчик","Если собираешься идти дальше, выбери дорогу до темноты. Не всякая встреча заканчивается разговором.")+
            "\n\nВ кошеле "+g.gold+" септимов. Здоровье "+g.hp+" из "+g.maxHp+
            "; выносливость "+g.stamina+" из "+g.maxStamina+
            ". Принятые поручения, пустеющие припасы и слухи, услышанные по дороге, могут повлиять на следующий шаг."+
            "\n\n"+s.body;
    }
    private static String intro(GameEngine g,GameEngine.Scene s){
        int r=region(g);
        return LANDSCAPES[r]+
            "\n\nПлащ цепляется за сухую ветку, под сапогом хрустит тонкая корка льда. Свою прежнюю жизнь ты оставил позади не целиком: привычки, мысли и давние обещания всегда находят дорогу обратно. Твоё имя, "+g.name+", пока ничего не говорит здешним людям. Они судят не по нему, а по тому, что ты делаешь, когда становится трудно."+
            "\n\n"+dialogue(VOICES[r],REMARKS[r])+
            "\n\nТы осматриваешь местность. В одной стороне слышен ритмичный стук работы, в другой дорога опускается к далёким огням. Невозможно заранее знать, какие из этих огней принадлежат трактиру, а какие зажгли на сторожевой башне. Но первый шаг уже сделан, и теперь придётся выбирать самому."+
            "\n\n"+s.body;
    }
    private static String quest(GameEngine g,GameEngine.Scene s){
        int phase=Math.max(0,Math.min(QUEST_MOMENTS.length-1,g.questStage));
        String line=phase<3?"Нам нужны доказательства, а не ещё одна легенда для трактирных вечеров.":
            phase==3?"Не каждый хранитель захочет принять то, что ты принёс. Смотри, кому доверяешь.":"Ты дал нам время. Как мы им распорядимся, зависит уже не только от тебя.";
        return QUEST_MOMENTS[phase]+"\n\n"+dialogue("Хранитель Эйрн",line)+
            "\n\nТы замечаешь, что собеседник избегает смотреть на один участок карты. Там чернила легли плотнее обычного, словно место пытались вычеркнуть. В лунном свете чернила блестят, и за старой бумагой просвечивает перечёркнутый знак. Подобные мелочи не всегда помогают победить врага, но порой объясняют, почему враг вообще появился."+
            "\n\n"+s.body+
            "\n\n"+dialogue("Хранитель Эйрн","Делай то, что считаешь правильным. Но когда вернёшься, расскажи и о том, что не удалось: это тоже может спасти жизнь.")+
            "\n\nТишина после этих слов кажется тяжелее самого поручения. Следующее решение останется твоим, даже если придётся отвечать за него перед другими.";
    }
    private static String travel(GameEngine g,GameEngine.Scene s){
        int r=region(g);
        return LANDSCAPES[r]+
            "\n\nУ развилки стоит дорожный камень с потёртыми буквами. На его вершине лежит мокрый снег, а вокруг так много старых следов, что определить направление последнего каравана непросто. Вдали поднимается дым, который может принадлежать торговой стоянке или заброшенному хутору. На привале приходится пересчитать припасы и решить, сколько дней можно идти без надёжного крова."+
            "\n\n"+dialogue("Возчик","На картах всё красиво. А в пути мост может обрушиться, тракт замести, и даже знакомая дорога станет чужой.")+
            "\n\nПопутчик проводит пальцем по грязной карте. Он показывает пересечения дорог владений, отмечает горные перевалы и осторожно обводит берег, откуда отправляются суда на Солстейм. За переправу нужно платить, но морской путь избавляет от ещё более опасных пеших обходов. Каждая остановка означает время, усталость и возможность новой встречи."+
            "\n\n"+s.body;
    }
    private static String talk(GameEngine g,GameEngine.Scene s){
        int r=region(g);
        return LANDSCAPES[r]+
            "\n\nТы подходишь ближе, не прерывая чужую беседу. Кто-то перелистывает письма у придорожного столика, кто-то тщательно скрывает усталость за показной резкостью. В разговоре бывают важны не только ответы: паузы, неловко отведённый взгляд и внезапная тишина иногда рассказывают куда больше. Собеседник оценивает твоё снаряжение и даёт понять, что не любит пустых вопросов."+
            "\n\n"+dialogue(s.title,REMARKS[r])+
            "\n\n"+s.body+
            "\n\nСлова повисают между вами. Человек ждёт ответа, но не делает попытки подсказать, какой именно. Ты можешь расспросить о слухах, предложить помощь или закончить разговор; любая из этих возможностей по-своему изменит то, как тебя запомнят."+
            "\n\n"+dialogue("Прохожий","Хочешь услышать правду, не торопи человека. А хочешь найти дорогу, сперва пойми, куда идёшь.");
    }
    private static String shop(GameEngine g,GameEngine.Scene s){
        int r=region(g);
        return LANDSCAPES[r]+
            "\n\nНад дверью лавки скрипит железный знак. Внутри пахнет кожей, копчёной древесиной и травяными настоями. На витрине рядом с походным оружием стоят бутылочки с тёмным стеклом; их этикетки кое-где выцвели, но торговец помнит каждую цену. У стены висит потёртая кираса, на которой видны следы старого ремонта. Ты замечаешь, как хозяин проверяет взглядом не столько твой кошелёк, сколько ремни на заплечной сумке."+
            "\n\n"+dialogue("Торговец","Прежде чем платить, убедись, что сможешь унести покупку. Я не стану возвращать септимы за товар, который ты оставишь на пороге.")+
            "\n\nНа деревянном прилавке разложены камешки для взвешивания. Торговец не спешит доставать лучшее снаряжение, пока ты не решишь, что именно тебе требуется: лекарство для опасного перехода, запас магии или сталь, которая выдержит встречу с разбойником."+
            "\n\n"+s.body;
    }
    private static String event(GameEngine g,GameEngine.Scene s){
        int r=region(g);
        return LANDSCAPES[r]+
            "\n\nНа дороге замечаешь следы недавней остановки: влажное пятно от котелка, тёмную полосу от повозки и несколько неосторожно брошенных тряпок. Ветер шевелит траву, и кажется, будто за ближайшим камнем кто-то притаился. Но не всякий звук предупреждает об угрозе, как не всякий зов о помощи бывает искренним."+
            "\n\n"+s.body+
            "\n\n"+dialogue("Незнакомец","Я не знаю, кому здесь можно доверять. Но, если проходишь мимо, хотя бы взгляни, нет ли за мной погони.")+
            "\n\nТы стараешься понять, что произошло раньше твоего прихода. В нескольких шагах земля примята неестественно ровно, будто кто-то пытался скрыть следы. Время для решения ограничено: даже осторожное обследование может привлечь чужое внимание. Помочь, исследовать или уйти означает принять разную меру риска, и каждое последствие останется на твоей совести.";
    }
    private static String battle(GameEngine g,GameEngine.Scene s){
        String enemy=g.enemyName.isEmpty()?"противник":g.enemyName;
        return "Ветер приносит запах холодной земли и пота. Между тобой и «"+enemy+
            "» остаётся несколько шагов; здесь любая мелочь способна решить исход схватки. Ты чувствуешь тяжесть снаряжения и вспоминаешь, что усталость подкрадывается незаметно. Враг наблюдает за твоими руками, выискивая ошибку."+
            "\n\n"+dialogue("Противник","Не рассчитывай, что я оставлю тебе время на раздумья.")+
            "\n\n"+s.body+
            "\n\nЗа мгновение до следующего движения особенно отчётливо слышно собственное дыхание. Можно ударить, попытаться вложить в атаку последние силы, применить магию или закрыться от ответного удара. Зелье даст передышку лишь при наличии запаса, а отступление возможно не при каждой встрече. Выбор теперь измеряется не словами, а тем, сколько здоровья останется после следующего удара.";
    }
    private static String result(GameEngine g,GameEngine.Scene s){
        int r=region(g);
        return LANDSCAPES[r]+
            "\n\nПроизошедшее ещё не отпускает тебя. Руки помнят только что сделанное движение, будто повторяют его снова и снова. На дороге всё продолжается прежним чередом: вдалеке идут люди, где-то скрипит телега, слышен лай собаки. Мир не останавливается из-за одной победы или ошибки, и именно поэтому последствия иногда становятся понятны лишь много позже."+
            "\n\n"+s.body+
            "\n\n"+dialogue(VOICES[r],"Ты сам выбрал этот путь. Теперь решай, что с ним делать дальше.")+
            "\n\nТы проверяешь снаряжение, смотришь на ближайшую дорогу и мысленно возвращаешься к принятому решению. Если удалось кому-то помочь, об этом узнают не сразу; если ошибся, исправить случившееся будет труднее. Но следующая развилка всё ещё перед тобой.";
    }
    private static String defeat(GameEngine g,GameEngine.Scene s){
        return "Сознание возвращается медленно. Сначала ты слышишь воду, падающую с карниза, потом различаешь в полутьме чужой костёр. Земля под спиной холодная, в руках дрожь, на языке привкус железа. Первым желанием становится немедленно подняться, но боль напоминает о цене поспешных решений."+
            "\n\n"+dialogue("Прохожий","Тебе повезло. Ещё немного, и я не успел бы ничего сделать.")+
            "\n\n"+s.body+
            "\n\nПоражение осталось позади, но потери реальны. Можно продолжить дорогу, осмотреть своё снаряжение и подумать о подготовке к следующему столкновению. Жизнь не требует притворяться непобедимым: иногда разумнее прийти снова с полным запасом сил.";
    }
    private static String dragon(GameEngine g,GameEngine.Scene s){
        String extra;
        switch(Math.max(0,Math.min(5,g.progress.dragonStage))){
            case 0:extra="Обугленная кладка хранит следы огня, который поднялся выше башен. Над пустыми дворами слышно, как ветер хлопает неплотно закрытой дверью. Здесь кто-то успел выжить только потому, что не поверил собственным глазам.";break;
            case 1:extra="Река у Ривервуда кажется спокойной, но жители вздрагивают даже от треска дров. На лесопилке меньше работают и больше прислушиваются. Твоё свидетельство может оказаться последним предупреждением перед бедой.";break;
            case 2:extra="В высоком зале над Вайтраном советники спорят, не замечая, как быстро гаснут свечи. У каждого свои доводы, и ни один не хочет первым признать, насколько мало известно о крылатой угрозе.";break;
            case 3:extra="Над западной башней вороны исчезли задолго до появления дракона. Люди пытаются закрепить щиты между обожжёнными балками, но часть гарнизона уже готова бежать.";break;
            case 4:extra="На дороге к Айварстеду снег лежит неровными полосами. Высокая гора скрывается за облаками; её вершина кажется другой частью мира, где привычные страхи ничего не значат.";break;
            default:extra="Тишина Высокого Хротгара похожа на испытание сама по себе. Каждый звук в пустом зале обретает вес, и даже собственный шаг кажется вопросом, на который ещё нужно ответить.";break;
        }
        return extra+"\n\n"+s.body+
            "\n\n"+dialogue("Пожилой путник","Герои редко знают, что станут героями, когда делают первый шаг. Зато каждый помнит, кого сумел спасти.")+
            "\n\nТы прислушиваешься к собственному дыханию. От принятых ранее решений зависит, кому ты можешь доверять и сколько сил осталось для дороги. Иногда шаг вперёд требует большего мужества, чем удар меча.";
    }
    public static GameEngine.Scene expand(GameEngine g,GameEngine.Scene s){
        if(g==null||s==null||!g.started)return s;
        String body;
        switch(g.mode){
            case "INTRO":body=intro(g,s);break;
            case "WORLD":body=world(g,s);break;
            case "TRAVEL":body=travel(g,s);break;
            case "QUEST":body=quest(g,s);break;
            case "DRAGON":body=dragon(g,s);break;
            case "TALK":body=talk(g,s);break;
            case "SHOP":body=shop(g,s);break;
            case "EVENT":body=event(g,s);break;
            case "COMBAT":body=battle(g,s);break;
            case "RESULT":body=result(g,s);break;
            case "DEFEAT":body=defeat(g,s);break;
            default:return s;
        }
        GameEngine.Scene rich=new GameEngine.Scene(s.kicker,s.title,body);
        rich.choices.addAll(s.choices);
        return rich;
    }
}
